import (
	expect_false from "@std/test/test.ms",
	parse from "@std/math/math.ms",
	BigInt from "@std/math/math.ms",
)

fn verify_bigint() Unit!:
	large := try parse(text: "18446744073709551616", radix: 10, max_digits: 30)
	(
		not (
			((large).multiply(other: large)).to_string_radix(
				radix: 10
			) == "340282366920938463463374607431768211456"
		)
	) | try expect_false

test "large integers are exact":
	try verify_bigint()
